  ('arabica-s18-clean', 'Arabica S18 Clean', 'coffee', 'G1 · Screen 18 · Washed', 'Fully washed high-altitude Arabica from Cau Dat with bright acidity and a sweet, clean finish.', 'Selectively picked on the cool slopes around Da Lat, pulped, fermented and fully washed before drying. Screen 18 beans with minimal defects suit single-origin programs and specialty blends that want citrus and honey notes.', 'https://images.unsplash.com/photo-1750967613671-297f1b63038d', array['https://images.unsplash.com/photo-1652015496419-58606c1b5d1c', 'https://images.unsplash.com/photo-1561986845-fbeb7f7913d8']::text[], 'Cau Dat, Lam Dong', '[{"label":"Moisture","value":"12.5% max"},{"label":"Foreign matter","value":"0.1% max"},{"label":"Black & broken","value":"0.1% max"},{"label":"Bean size","value":"90% above Screen 18"},{"label":"Processing","value":"Fully washed"},{"label":"Grade","value":"G1 · Premium"}]'::jsonb, '60 kg jute bags, PP bags, 1 MT jumbo bags or bulk', '1 × 20ft container (19.2 MT)', true, 40, '{"ru":{"name":"Арабика S18, очищенная","grade":"G1 · скрин 18 · мытая","summary":"Полностью мытая высокогорная арабика из Каудат с яркой кислотностью и сладким чистым послевкусием.","description":"Выборочно собрана на прохладных склонах вокруг Далата, депульпирована, ферментирована и полностью промыта перед сушкой. Зерно скрин 18 с минимумом дефектов подходит для моносортовых программ и спешелти-бленд с цитрусовыми и медовыми нотами.","origin":"Каудат, Ламдонг","specs":[{"label":"Влажность","value":"не более 12,5%"},{"label":"Посторонние примеси","value":"не более 0,1%"},{"label":"Чёрные и битые зёрна","value":"не более 0,1%"},{"label":"Размер зерна","value":"90% выше скрина 18"},{"label":"Обработка","value":"Полностью мытая"},{"label":"Сорт","value":"G1 · премиум"}],"packaging":"Джутовые мешки по 60 кг, мешки PP, биг-бэги 1 т или навалом","moq":"1 × 20ft контейнер (19,2 т)"},"ar":{"name":"أرابيكا S18 نظيفة","grade":"G1 · غربال 18 · مغسولة","summary":"أرابيكا مغسولة بالكامل 