0 بعناية وتُقشّر وتُنزع أغلفتها وتُفرز يدويًا وآليًا في بينه فوك، عاصمة الكاجو في فيتنام. لون أبيض كريمي وطعم حلو وقرمشة مميزة.","origin":"بينه فوك، جنوب شرق فيتنام","specs":[{"label":"العدد","value":"220 – 240 حبة/رطل"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"المكسور","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"المحصول","value":"2026"}],"packaging":"علب صفيح مفرّغة أو أكياس فويل، 2 × 25 رطلًا في الكرتونة","moq":"حاوية 20 قدم واحدة (نحو 700 كرتونة)"}}'::jsonb, true),
  ('cashew-kernels-w320', 'Cashew Kernels W320', 'cashew', 'White Wholes · 320', 'The world''s most traded cashew grade — consistent size and color for snacking and roasting.', 'Our best-selling grade, W320 balances size and value. Kernels are graded to AFI standards and packed in nitrogen-flushed bags to lock in freshness for long ocean transits.', 'https://images.unsplash.com/photo-1573555657105-47a0bb37c3ea', array['https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', 'https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c']::text[], 'Binh Phuoc, Southeast Vietnam', '[{"label":"Count","value":"300 – 320 kernels/lb"},{"label":"Moisture","value":"5% max"},{"label":"Broken","value":"5% max"},{"label":"Color","value":"White to ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Crop","value":"2026"}]'::jsonb, 'Vacuum-packed tins or foil bags, 2 × 25 lbs per carton', '1 × 20ft container (~700 cartons)', true, 120, '{"ru":{"name":"Ядра кешью W320","grade":"Белые цельные · 320","summary":"Самый продаваемый в мире сорт кешью — стабильный размер и цвет для снеков и обжарки.","description":"Наш самый популярный сорт: W320 — баланс размера и цены. Ядра сортируются по стандартам AFI и упаковываются в пакеты с азотом, чтобы сохранить свежесть при долгой морской перевозке.","origin":"Биньфыок, юго-восток Вьетнама","specs":[{"label":"Калибр","value":"300 – 320 ядер/фунт"},{"label":"Влажность","value":"не более 5%"},{"label":"Битые ядра","value":"не более 5%"},{"label":"Цвет","value":"Белый — слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Урожай","value":"2026"}],"packaging":"Вакуумные жестяные банки или фольгированные пакеты, 2 × 25 фунтов в коробке","moq":"1 × 20ft контейнер (~700 коробок)"},"ar":{"name":"كاجو W320","grade":"كاجو أبيض كامل · 320","summary":"أكثر درجات الكاجو تداولًا في العالم — حجم ولون ثابتان للوجبات الخفيفة والتحميص.","description":"درجتنا الأكثر مبيعًا، إذ توازن W320 بين الحجم والقيمة. تُفرز الحبات وفق معايير AFI وتُعبّأ في أكياس مشبعة بالنيتروجين للحفاظ على طزاجتها خلال رحلات الشحن البحري الطويلة.","origin":"بينه فوك، جنوب شرق فيتنام","specs":[{"label":"العدد","value":"300 – 320 حبة/رطل"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"المكسور","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"المحصول","value":"2026"}],"packaging":"علب صفيح مفرّغة أو أكياس فويل، 2 × 25 رطلًا في الكرتونة","moq":"حاوية 20 قدم واحدة (نحو 700 كرتونة)"}}'::jsonb, true),
  ('cashew-splits-and-pieces', 'Cashew Splits & Pieces', 'cashew', 'WS · LP · SP', 'Naturally split kernels and large pieces for bakeries, confectionery, nut butters and ingredients.', 'White Splits (WS), Large Pieces (LP) and Small Pieces (SP) deliver the same flavor as wholes at a better price for ingredient applications where shape doesn''t matter.', 'https://images.unsplash.com/photo-1686721635283-70e6344183e1', array['https://images.unsplash.com/photo-1573555657105-47a0bb37c3ea', 'https://images.unsplash.com/photo-1729514256038-c489695f4d79']::text[], 'Binh Phuoc, Southeast Vietnam', '[{"label":"Grades","value":"WS, LP, SP, BB"},{"label":"Moisture","value":"5% max"},{"label":"Color","value":"White to ivory"},{"label":"Standard","value":"AFI specification"},{"label":"Applications","value":"Bakery, butter, snacks"},{"label":"Crop","value":"2026"}]'::jsonb, 'Vacuum-packed foil bags, 2 × 25 lbs per carton', '1 × 20ft container', false, 130, '{"ru":{"name":"Половинки и кусочки кешью","grade":"WS · LP · SP","summary":"Естественные половинки и крупные кусочки для пекарен, кондитерских изделий, ореховых паст и ингредиентов.","description":"Белые половинки (WS), крупные кусочки (LP) и мелкие кусочки (SP) дают тот же вкус, что и цельные ядра, по более выгодной цене — для применений, где форма не важна.","origin":"Биньфыок, юго-восток Вьетнама","specs":[{"label":"Сорта","value":"WS, LP, SP, BB"},{"label":"Влажность","value":"не более 5%"},{"label":"Цвет","value":"Белый — слоновая кость"},{"label":"Стандарт","value":"Спецификация AFI"},{"label":"Применение","value":"Выпечка, пасты, снеки"},{"label":"Урожай","value":"2026"}],"packaging":"Вакуумные фольгированные пакеты, 2 × 25 фунтов в коробке","moq":"1 × 20ft контейнер"},"ar":{"name":"أنصاف وقطع الكاجو","grade":"WS · LP · SP","summary":"أنصاف طبيعية وقطع كبيرة للمخابز والحلويات وزبدة المكسرات والمكوّنات الغذائية.","description":"الأنصاف البيضاء (WS) والقطع الكبيرة (LP) والقطع الصغيرة (SP) تمنح النكهة نفسها للحبات الكاملة بسعر أفضل، للاستخدامات التي لا يهم فيها الشكل.","origin":"بينه فوك، جنوب شرق فيتنام","specs":[{"label":"الدرجات","value":"WS، LP، SP، BB"},{"label":"الرطوبة","value":"5% كحد أقصى"},{"label":"اللون","value":"أبيض إلى عاجي"},{"label":"المعيار","value":"مواصفات AFI"},{"label":"الاستخدامات","value":"المخبوزات، الزبدة، الوجبات الخفيفة"},{"label":"المحصول","value":"2026"}],"packaging":"أكياس فويل مفرّغة، 2 × 25 رطلًا في الكرتونة","moq":"حاوية 20 قدم واحدة"}}'::jsonb, true),
  ('roasted-salted-cashews', 'Roasted Salted Cashews', 'cashew', 'Ready-to-eat · W240/W320', 'Dry-roasted and lightly salted, packed in bulk or retail formats under your own brand.', 'Whole kernels roasted in small batches and seasoned with sea salt. Available in bulk cartons for repacking or in finished retail packs with your branding.', 'https://images.unsplash.com/photo-1509912760195-4f6cfd8cce2c', array['https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', 'https://images.unsplash.com/photo-1729514256038-c489695f4d79']::text[], 'Processed in Binh Phuoc', '[{"label":"Base grade","value":"W240 or W320"},{"label":"Roast","value":"Dry roasted"},{"label":"Seasoning","value":"Sea salt, or unsalted"},{"label":"Moisture","value":"3% max"},{"label":"Shelf life","value":"12 months"},{"label":"Branding","value":"Private label available"}]'::jsonb, 'Bulk 10 kg cartons or retail jars and pouches', '5 MT', false, 140, '{"ru":{"name":"Обжаренный солёный кешью","grade":"Готовый к употреблению · W240/W320","summary":"Обжаренный без масла и слегка подсоленный кешью — навалом или в розничной упаковке под вашим брендом.","description":"Цельные ядра обжариваются небольшими партиями и приправляются морской солью. Поставляем в коробках навалом для перефасовки или в готовой розничной упаковке с вашим брендом.","origin":"Переработка в Биньфыоке","specs":[{"label":"Базовый сорт","value":"W240 или W320"},{"label":"Обжарка","value":"Сухая"},{"label":"Приправа","value":"Морская соль или без соли"},{"label":"Влажность","value":"не более 3%"},{"label":"Срок годности","value":"12 месяцев"},{"label":"Брендинг","value":"Возможна СТМ"}],"packaging":"Коробки навалом по 10 кг или розничные банки и дой-паки","moq":"5 т"},"ar":{"name":"كاجو محمّص مملّح","grade":"جاهز للأكل · W240/W320","summary":"كاجو محمّص جافًا ومملّح قليلًا، يُعبّأ بالجملة أو في عبوات تجزئة باسم علامتكم.","description":"تُحمّص الحبات الكاملة على دفعات صغيرة وتُتبّل بملح البحر. متوفر في كرتونات بالجملة لإعادة التعبئة أو في عبوات تجزئة جاهزة تحمل علامتكم.","origin":"معالَج في بينه فوك","specs":[{"label":"الدرجة الأساسية","value":"W240 أو W320"},{"label":"التحميص","value":"تحميص جاف"},{"label":"التتبيل","value":"ملح البحر أو بدون ملح"},{"label":"الرطوبة","value":"3% كحد أقصى"},{"label":"مدة الصلاحية","value":"12 شهرًا"},{"label":"العلامة","value":"العلامة الخاصة متاحة"}],"packaging":"كرتونات جملة 10 كغ أو برطمانات وعبوات تجزئة","moq":"5 أطنان"}}'::jsonb, true)
) as v(slug, name, category, grade, summary, description, image, gallery, origin, specs, packaging, moq, featured, sort_order, translations, is_sample)
where not exists (select 1 from public.products);

insert into public.testimonials (quote, name, role, company, country, flag, product_slug, since, rating, image, logo, translations, is_sample, published, sort_order)
select * from (values
  ('Every container of Robusta S18 has matched the pre-shipment sample. That consistency is exactly what our espresso blends need.', 'Lena Hoffmann', 'Head of Green Coffee', 'Kestrel Roastery', 'Germany', '🇩🇪', 'robusta-s18-clean', 2021, 5, 'https://images.unsplash.com/photo-1561986845-fbeb7f7913d8', null, '{"ru":{"quote":"Каждый контейнер робусты S18 полностью соответствовал предотгрузочному образцу. Именно такая стабильность нужна нашим эспрессо-блендам.","role":"Руководитель закупок зелёного кофе","country":"Германия"},"ar":{"quote":"طابقت كل حاوية من روبوستا S18 عيّنة ما قبل الشحن. هذا الثبات هو بالضبط ما تحتاجه خلطات الإسبريسو لدينا.","role":"رئيسة مشتريات البن الأخضر","country":"ألمانيا"}}'::jsonb, true, true, 10),
  ('Clear specs, quick documents and honest updates when vessels were delayed. Switching our W320 supply to Cao Gia was easy.', 'Marcus Reid', 'Procurement Manager', 'Mirabel Foods', 'United States', '🇺🇸', 'cashew-kernels-w320', 2022, 5, 'https://images.unsplash.com/photo-1723466998040-78d7e2ef6d72', null, '{"ru":{"quote":"Понятные спецификации, быстрые документы и честная информация о задержках судов. Перевести закупки W320 на Cao Gia было просто.","role":"Менеджер по закупкам","country":"США"},"ar":{"quote":"مواصفات واضحة ومستندات سريعة وتحديثات صادقة عند تأخر السفن. كان نقل توريد W320 إلى كاو جيا أمرًا سهلًا.","role":"مدير المشتريات","country":"الولايات المتحدة"}}'::jsonb, true, true, 20),
  ('Their Cau Dat Arabica surprised our customers. The team helped us plan a forward contract for the whole season.', 'Aiko Tanaka', 'Founder', 'Sable Street Coffee', 'Japan', '🇯🇵', 'arabica-s18-clean', 2020, 5, 'https://images.unsplash.com/photo-1750967613671-297f1b63038d', null, '{"ru":{"quote":"Арабика из Каудат удивила наших клиентов. Команда помогла спланировать форвардный контракт на весь сезон.","role":"Основатель","country":"Япония"},"ar":{"quote":"فاجأت أرابيكا كاو دات عملاءنا. وساعدنا الفريق في التخطيط لعقد آجل يغطي الموسم كاملًا.","role":"المؤسسة","country":"اليابان"}}'::jsonb, true, true, 30),
  ('Private-label roasted coffee delivered on schedule with our branding. The samples process was fast and professional.', 'Omar Haddad', 'Category Buyer', 'Lumen Nut Co.', 'United Arab Emirates', '🇦🇪', null, 2023, 5, 'https://images.unsplash.com/photo-1447933601403-0c6688de566e', null, '{"ru":{"quote":"Обжаренный кофе под нашей маркой пришёл точно в срок. Работа с образцами — быстрая и профессиональная.","role":"Категорийный менеджер","country":"ОАЭ"},"ar":{"quote":"وصلت القهوة المحمّصة بعلامتنا الخاصة في موعدها. وكانت إجراءات العيّنات سريعة واحترافية.","role":"مسؤول مشتريات الفئة","country":"الإمارات العربية المتحدة"}}'::jsonb, true, true, 40)
) as v(quote, name, role, company, country, flag, product_slug, since, rating, image, logo, translations, is_sample, published, sort_order)
where not exists (select 1 from public.testimonials);

