insert into public.team_members (name, role, bio, quote, photo, email, whatsapp, is_ceo, translations, is_sample, published, sort_order)
select * from (values
  ('Cao Minh Duc', 'Founder & CEO', array['Leads Cao Gia''s export business, from building relationships with partner farms to agreeing specifications and delivery programs with buyers overseas.', 'Sets the company''s standard: specifications written down, samples approved before shipment and every container documented from farm to port.']::text[], 'Every container carries our name. We would rather say no to an order than ship a lot we wouldn''t buy ourselves.', null, 'caogiaxk2022@gmail.com', '+84 867 282 139', true, '{"ru":{"role":"Основатель и генеральный директор","bio":["Руководит экспортным направлением Cao Gia — от выстраивания отношений с фермами-партнёрами до согласования спецификаций и программ поставок с зарубежными покупателями.","Задаёт стандарт компании: спецификации фиксируются письменно, образцы одобряются до отгрузки, а каждый контейнер документируется от фермы до порта."],"quote":"Каждый контейнер несёт наше имя. Мы скорее откажемся от заказа, чем отгрузим партию, которую не купили бы сами."},"ar":{"role":"المؤسس والرئيس التنفيذي","bio":["يقود أعمال التصدير في كاو جيا، من بناء العلاقات مع المزارع الشريكة إلى الاتفاق على المواصفات وبرامج التوريد مع المشترين في الخارج.","يضع معيار الشركة: مواصفات مكتوبة، وعيّنات تُعتمد قبل الشحن، وتوثيق كل حاوية من المزرعة إلى الميناء."],"quote":"كل حاوية تحمل اسمنا. نفضّل رفض طلب على شحن دفعة لا نشتريها بأنفسنا."}}'::jsonb, true, true, 10),
  ('David Cao', 'Director of Marketing', array[]::text[], '', null, 'davidcaocg@gmail.com', '+84 867 282 139', false, '{"ru":{"role":"Директор по маркетингу"},"ar":{"role":"مدير التسويق"}}'::jsonb, false, true, 20)
) as v(name, role, bio, quote, photo, email, whatsapp, is_ceo, translations, is_sample, published, sort_order)
where not exists (select 1 from public.team_members);

